                subdir0 = (os.path.join(
                    parent, "matrix", "00-user-ada-plan-pro")
                    if parent else "")
                subdir1 = (os.path.join(
                    parent, "matrix", "01-user-bob-plan-free")
                    if parent else "")
                sub0_data = {}
