        '        ln = int(self.headers.get("Content-Length", 0))',
        "        self.rfile.read(ln)",
        '        i = min(state["n"], len(SCRIPT) - 1)',
        '        state["n"] += 1',
        "        body = json.dumps({",
        '            "choices": [{"message": {"role": "assistant",',
        "                                     \"content\": json.dumps(SCRIPT[i])}}],",
        '            "usage": {"prompt_tokens": 800, "completion_tokens": 60},',
