            check("521 baselines-partial-boot-failed e2e: run dir "
                  "holds exactly the services and steps entries",
                  entries == ["services", "steps"], str(entries))
            run_dir_files = []
            if only_dir:
                for dirpath, _dirnames, filenames in os.walk(
                        only_dir):
                    for name in filenames:
                        run_dir_files.append(os.path.relpath(
                            os.path.join(dirpath, name), only_dir))
                run_dir_files = sorted(
                    p.replace(os.sep, "/")
                    for p in run_dir_files)
            check("521 baselines-partial-boot-failed e2e: run dir "
                  "file inventory is exactly the first "
                  "service log",
                  run_dir_files == ["services/first.log"],
                  str(run_dir_files))
            rows = ledger.read_all()
