    check("529 verify-log-contains-services-success e2e: exact "
          "expectations return no mismatch",
          verify_log_contains_services_success_mismatch(
              dict(exp), exp) is None)
    probe = verify_log_contains_services_success_mismatch(
        dict(exp, exit_code=1), exp)
